+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        self.pending = None;
+        self.mode = UiMode::Command;
+        let pane = if self.focus == PaneFocus::Left && self.left_visible {
+            PaneFocus::Left
+        } else {
+            PaneFocus::Right
+        };
+        let (lines, position) = match pane {
+            PaneFocus::Left => {
+                let lines = self.left_visual_lines();
+                let row = self.control_selection_visual_row();
+                (lines, TextPosition { row, column: 0 })
+            }
+            PaneFocus::Right => {
+                let visible = self.visible_right_content(right_content);
+                let lines = content_lines(&visible);
+                let row = lines.len().saturating_sub(1);
+                let column = lines
+                    .get(row)
+                    .map(|line| {
+                        let line_len = line_char_count(line);
+                        right_cursor_column
+                            .unwrap_or(line_len)
+                            .min(line_len.saturating_sub(1))
+                    })
+                    .unwrap_or(0);
+                (lines, TextPosition { row, column })
+            }
+        };
+        let lines = if lines.is_empty() {
+            vec![String::new()]
+        } else {
+            lines
+        };
+        let position = clamp_text_position(position, &lines);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+            lines,
+        });
+    }
+
+    fn copy_visual_selection(&mut self, linewise: bool) -> Option<String> {
+        let text = self
+            .visual_selection
+            .as_ref()
+            .map(|selection| selection.selected_text(linewise))?;
+        self.visual_selection = None;
+        self.clipboard_text = Some(text.clone());
+        self.pending_clipboard_text.replace(Some(text.clone()));
+        self.show_status_notice(
+            "selection copied",
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+        Some(text)
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        let max_row = selection.lines.len().saturating_sub(1);
+        let row = if row_delta < 0 {
+            selection.cursor.row.saturating_sub(row_delta.unsigned_abs())
+        } else {
+            selection
+                .cursor
+                .row
+                .saturating_add(row_delta as usize)
+                .min(max_row)
+        };
+        let line_len = selection
+            .lines
+            .get(row)
+            .map(|line| line_char_count(line))
+            .unwrap_or(0);
+        let max_column = line_len.saturating_sub(1);
+        let column = if column_delta < 0 {
+            selection.cursor.column.saturating_sub(column_delta.unsigned_abs())
+        } else {
+            selection
+                .cursor
+                .column
+                .saturating_add(column_delta as usize)
+        }
+        .min(max_column);
+        selection.cursor = TextPosition {
+            row,
+            column,
+        };
+    }
+
+    fn left_visual_lines(&self) -> Vec<String> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut lines = vec![truncate_to_width(
+            if self.control_selected == 0 {
+                "> work-leaf  command"
+            } else {
+                "  work-leaf  command"
+            },
+            inner_width,
+        )];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            lines.push(compact_agent_row(
+                agent,
+                self.control_selected == visible_position + 1,
+                inner_width,
+            ));
+            if !agent.modified_files.is_empty() {
+                lines.push(truncate_to_width(
+                    &format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    inner_width,
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(truncate_to_width(
+                        &format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        inner_width,
+                    ));
+                }
+            }
+        }
+        lines
+    }
+
+    fn control_selection_visual_row(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+
+        let mut current_row = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            if self.control_selected == visible_position + 1 {
+                return current_row;
+            }
+            current_row += 1;
+            if !agent.modified_files.is_empty() {
+                current_row += 1;
+            }
+            for linked_agents in [
+                &agent.conflicting_agents,
+                &agent.depends_on,
+                &agent.depended_on_by,
+            ] {
+                if !linked_agents.is_empty() {
+                    current_row += 1;
+                }
+            }
+        }
+        0
+    }
+
+    fn apply_visual_selection_to_buffer(&self, buffer: &mut Buffer) {
+        let Some(selection) = &self.visual_selection else {
+            return;
+        };
+        let layout = self.layout();
+        let body_height = self.height.saturating_sub(1);
+        let inner_height = body_height.saturating_sub(2);
+        if inner_height == 0 {
+            return;
+        }
+
+        match selection.pane {
+            PaneFocus::Left if self.left_visible => {
+                let inner_width = layout.left_width.saturating_sub(2).max(1);
+                let max_column = usize::from(inner_width.saturating_sub(1));
+                for (row, start, end) in selection.row_ranges(false) {
+                    if row >= usize::from(inner_height) {
+                        continue;
+                    }
+                    let start = start.min(max_column);
+                    let end = end.min(max_column);
+                    for column in start..=end {
+                        reverse_buffer_cell(buffer, column as u16 + 1, row as u16 + 1);
+                    }
+                }
+            }
+            PaneFocus::Right => {
+                let inner_width = layout.right_width.saturating_sub(2).max(1);
+                let origin_x = if self.left_visible {
+                    layout.left_width.saturating_add(1)
+                } else {
+                    1
+                };
+                let mut ranges = selection.row_ranges(false).into_iter().peekable();
+                let mut visual_row = 0_usize;
+                for (line_index, line) in selection.lines.iter().enumerate() {
+                    while matches!(ranges.peek(), Some((row, _, _)) if *row == line_index) {
+                        let (_, start, end) = ranges.next().expect("range is present");
+                        style_wrapped_range(
+                            buffer,
+                            origin_x,
+                            1,
+                            inner_width,
+                            inner_height,
+                            visual_row,
+                            start,
+                            end,
+                        );
+                    }
+                    visual_row =
+                        visual_row.saturating_add(visual_row_count(line, inner_width));
+                }
+            }
+            PaneFocus::Left => {}
+        }
+    }
+
+    fn visual_cursor_position(&self) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        let layout = self.layout();
+        match selection.pane {
+            PaneFocus::Left if self.left_visible => Some((
+                selection.cursor.row.saturating_add(2).min(usize::from(u16::MAX)) as u16,
+                selection
+                    .cursor
+                    .column
+                    .saturating_add(2)
+                    .min(usize::from(u16::MAX)) as u16,
+            )),
+            PaneFocus::Right => {
+                let inner_width = layout.right_width.saturating_sub(2).max(1);
+                let previous_rows = selection
+                    .lines
+                    .iter()
+                    .take(selection.cursor.row)
+                    .map(|line| visual_row_count(line, inner_width))
+                    .sum::<usize>();
+                let row = 2_usize
+                    .saturating_add(previous_rows)
+                    .saturating_add(selection.cursor.column / usize::from(inner_width));
+                let column = usize::from(layout.left_width)
+                    .saturating_add(2)
+                    .saturating_add(selection.cursor.column % usize::from(inner_width));
+                Some((
+                    row.min(usize::from(u16::MAX)) as u16,
+                    column.min(usize::from(u16::MAX)) as u16,
+                ))
+            }
+            PaneFocus::Left => None,
+        }
+    }

