use std::time::Duration;

use work_leaf::{
    CodexBackend, CodexCommandConfig, CommandChat, PromptPolicy, WorkLeafController,
};

#[test]
fn selected_agent_slash_commands_use_real_codex_command_path() {
    let root = std::env::var("WORK_LEAF_REPO").expect("repo path set");
    let backend = CodexBackend::new(
        CodexCommandConfig::new(PathBuf::from(&root)),
        PromptPolicy::for_restricted_agents(),
    );
    let chat = CommandChat::new(PathBuf::from(root), backend);
    let mut controller = WorkLeafController::new(chat);

    let agent_id = controller
        .create_agent("Reply exactly with READY_FOR_SLASH_COMMANDS and do not modify files.")
        .expect("agent launch starts");
    assert!(controller.wait_for_idle(Duration::from_secs(90)), "launch should finish");
    assert!(
        controller.wait_for_session_line(
            &agent_id,
            "READY_FOR_SLASH_COMMANDS",
            Duration::from_secs(5),
        ),
        "launch reply should be visible in selected agent chat"
    );

    controller
        .send_message(&agent_id, "/status")
        .expect("status command accepted");
    assert!(
        controller.wait_for_session_line(&agent_id, "user: /status", Duration::from_secs(5)),
        "selected chat should show submitted /status"
    );
    assert!(controller.wait_for_idle(Duration::from_secs(90)), "status command should finish");

    controller
        .send_message(&agent_id, "/fork real-slash-smoke")
        .expect("fork command accepted");
    assert!(
        controller.wait_for_session_line(
            &agent_id,
            "user: /fork real-slash-smoke",
            Duration::from_secs(5),
        ),
        "selected chat should show submitted /fork"
    );
    assert!(controller.wait_for_idle(Duration::from_secs(90)), "fork command should finish");

    let snapshot = controller.snapshot();
    let session = snapshot.session(&agent_id).expect("session exists");
    let transcript = session.lines.join("\n");
    println!("REAL_SLASH_TRANSCRIPT_START\n{}\nREAL_SLASH_TRANSCRIPT_END", transcript);
    assert!(transcript.contains("user: /status"), "{}", transcript);
    assert!(transcript.contains("user: /fork real-slash-smoke"), "{}", transcript);
    assert!(session.lines.len() >= 5, "selected chat should include launch output and backend command outputs: {}", transcript);
}
